package mz.co.aprendaacodar.enrollment.service;
import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.course.entity.Course;import mz.co.aprendaacodar.course.repository.CourseRepository;import mz.co.aprendaacodar.enrollment.dto.EnrollmentDtos.*;import mz.co.aprendaacodar.enrollment.entity.CourseEnrollment;import mz.co.aprendaacodar.enrollment.repository.EnrollmentRepository;import mz.co.aprendaacodar.user.entity.User;import mz.co.aprendaacodar.user.repository.UserRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
import mz.co.aprendaacodar.audit.service.AuditService;
@Service public class EnrollmentService {
 private final EnrollmentRepository enrollments;private final CourseRepository courses;private final UserRepository users;private final AuditService audit;
 public EnrollmentService(EnrollmentRepository e,CourseRepository c,UserRepository u,AuditService audit){enrollments=e;courses=c;users=u;this.audit=audit;}
 @Transactional public Response request(UUID studentId,UUID courseId){Course c=courses.findById(courseId).orElseThrow(()->new ResourceNotFoundException("Curso não encontrado."));if(c.getStatus()!=CourseStatus.PUBLISHED)throw new BusinessException("O curso não está disponível para inscrição.");User s=user(studentId);if(s.getRole()!=UserRole.STUDENT)throw new ForbiddenOperationException("Apenas estudantes podem inscrever-se.");CourseEnrollment e=enrollments.findByStudentIdAndCourseId(studentId,courseId).orElse(null);if(e!=null){if(e.getStatus()==EnrollmentStatus.ACTIVE||e.getStatus()==EnrollmentStatus.PENDING_PAYMENT||e.getStatus()==EnrollmentStatus.UNDER_REVIEW)throw new BusinessException("Já existe uma inscrição ativa ou pendente.");throw new BusinessException("A inscrição existente deve ser tratada pelo administrador.");}return map(enrollments.save(new CourseEnrollment(s,c,EnrollmentStatus.PENDING_PAYMENT,EnrollmentSource.PAYMENT,c.getPrice(),c.getCurrency())));}
 @Transactional(readOnly=true) public List<Response> mine(UUID student){return enrollments.findAllByStudentId(student).stream().map(this::map).toList();}@Transactional(readOnly=true) public List<Response> all(){return enrollments.findAll().stream().map(this::map).toList();}
 @Transactional(readOnly=true) public Response get(UUID actor,UUID id,boolean admin){CourseEnrollment e=find(id);if(!admin&&!e.getStudent().getId().equals(actor))throw new ForbiddenOperationException("Não pode consultar esta inscrição.");return map(e);}
 public void assertStudentOwner(UUID actor,UUID enrollmentId){CourseEnrollment e=find(enrollmentId);if(!e.getStudent().getId().equals(actor))throw new ForbiddenOperationException("A inscrição não pertence ao utilizador autenticado.");}
 public boolean hasActiveAccess(UUID actor,UUID courseId){return enrollments.existsByStudentIdAndCourseIdAndStatus(actor,courseId,EnrollmentStatus.ACTIVE);}
 @Transactional public Response grant(UUID admin,UUID studentId,UUID courseId,String reason){User actor=user(admin);User s=user(studentId);if(s.getRole()!=UserRole.STUDENT)throw new BusinessException("O utilizador indicado não é estudante.");Course c=courses.findById(courseId).orElseThrow(()->new ResourceNotFoundException("Curso não encontrado."));CourseEnrollment e=enrollments.findByStudentIdAndCourseId(studentId,courseId).orElseGet(()->new CourseEnrollment(s,c,EnrollmentStatus.ACTIVE,EnrollmentSource.ADMIN,c.getPrice(),c.getCurrency()));e.activate(actor,EnrollmentSource.ADMIN);CourseEnrollment saved=enrollments.save(e);audit.record(actor,"ACCESS_GRANTED","CourseEnrollment",saved.getId(),Map.of("studentId",studentId.toString(),"courseId",courseId.toString(),"reason",reason));return map(saved);}
 @Transactional public void revoke(UUID admin,UUID id,String reason){User actor=user(admin);find(id).revoke(actor,reason);audit.record(actor,"ACCESS_REVOKED","CourseEnrollment",id,Map.of("reason",reason));}
 CourseEnrollment find(UUID id){return enrollments.findById(id).orElseThrow(()->new ResourceNotFoundException("Inscrição não encontrada."));}User user(UUID id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));}
 private Response map(CourseEnrollment e){return new Response(e.getId(),e.getStudent().getId(),e.getCourse().getId(),e.getCourse().getTitle(),e.getStatus(),e.getSource(),e.getAgreedPrice(),e.getCurrency(),e.getEnrolledAt(),e.getActivatedAt());}
}
